local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[36719] = {id=36719,name="Into Aegwynn's Retreat",level=10,requiredLevel=10,faction="none",expansion=10,description="If we're going to defeat that demon, we need something to put us on its level. Something... powerful... You need a weapon. Something of great power. And if my assumptions are correct, it shouldn't be too far from here. I can send you to go find this weapon. Speak with me when you're prepared.",questType="standard"},
[40801] = {id=40801,name="Journey to Azsuna",level=10,requiredLevel=10,faction="none",expansion=10,description="t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity. The Kirin Tor have also constructed a permanent waygate to enable speedy movement between here and Dalaran - you can find it near the path down in the village should you wish to use it.",questType="standard"},
[41830] = {id=41830,name="Demon's Bite",level=45,requiredLevel=45,faction="none",expansion=10,zoneID=7503,mapID=650,questType="world"},
[43181] = {id=43181,name="Tracking Down the Scepter",level=10,requiredLevel=10,faction="none",expansion=10,description="The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.",questType="standard"},
[45030] = {id=45030,name="The Fel-Etched Bone",level=45,requiredLevel=45,faction="none",expansion=10,questType="standard"},
[45033] = {id=45033,name="The Inferno Stone",level=45,requiredLevel=45,faction="none",expansion=10,questType="standard"},
[45037] = {id=45037,name="The Locket of Eldre'Thalas",level=45,requiredLevel=45,faction="none",expansion=10,questType="standard"},
[45746] = {id=45746,name="Salvation",level=45,requiredLevel=45,faction="none",expansion=10,zoneID=7334,mapID=630,description="The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help. Take this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.",questType="standard"},
[49578] = {id=49578,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",expansion=10,description="I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun. It's a foreboding desert, full of canyons, with a great pyramid in the center. If my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map. And let's hope it's still in one piece.",questType="standard"},
[49579] = {id=49579,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",expansion=10,description="This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire. Well, maybe not the main city itself, but close to it. Actually... Ah, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of. Here are you notes for the shrine and the location for it should be marked on your map.",questType="standard"},
[49580] = {id=49580,name="REUSE ME",level=10,requiredLevel=10,faction="alliance",expansion=10,description="The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls. Luckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct... It should be right there. Take note of its location and here are the notes for that shrine. Good luck, .",questType="standard"},
[49945] = {id=49945,name="First Impressions",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=10565,mapID=1670,questType="standard"},
[49947] = {id=49947,name="Blood Bonded",level=10,requiredLevel=10,faction="horde",expansion=10,questType="standard"},
[49948] = {id=49948,name="The Final Verse",level=10,requiredLevel=10,faction="horde",expansion=10,questType="standard"},
[50326] = {id=50326,name="Ain't No Place Like Home",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=9439,mapID=14,description="Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base. How about I help you out with that?",ends={{npcID=131602,x=0.608,y=0.252,mapID=14}},questType="standard"},
[57308] = {id=57308,name="The Battle of Alterac",level=10,requiredLevel=10,faction="none",expansion=10,description="The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar. With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley. Vanquish him, and then return to me.",questType="pvp"},
[57319] = {id=57319,name="The Battle for Alterac",level=10,requiredLevel=10,faction="none",expansion=10,description="The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike! You will find Vanndar in Dun Baldar, in the north of Alterac Valley. Destroy him, , and then return to me.",questType="pvp"},
[70707] = {id=70707,name="The Next Waygate",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=13644,mapID=2022,description="I've been keepin' this here vessel from yer nightborne friend safe. What do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?",questType="standard"},
[71025] = {id=71025,name="Against Overwhelming Odds",level=70,requiredLevel=70,faction="horde",expansion=10,questType="standard"},
[75022] = {id=75022,name="Vinyeti",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,questType="standard"},
[75024] = {id=75024,name="Sneaky Pebbles",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Beetles are swarming our support creche! Some of them are now eating pieces of broken Infusers, and that's making them stronger. We keep trying to smush them, but they won't stay smushed. Now it's harder to get rid of them, but we have a plan. We've discovered that hitting them with pieces of broken Infusers can weaken them again! Do you mind helping us clear out these Infused Beetles?",starts={{npcID=200727,x=0.348,y=0.574,zoneID=14433}},ends={{npcID=200727,x=0.348,y=0.574,zoneID=14433}},coords={x=0.348,y=0.574,source="quest_giver",zoneID=14433},questType="standard"},
[75025] = {id=75025,name="A Good Day for Rolling",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="I have an... odd request for you. I need help with some squirrels. Primalists have corrupted them, and it's making them unstable! I know just the thing to cool them off. Snow! If you could roll the creatures up in a big snowball, they would cool down as the snow melts. Ingenious, yes? Can you help me? I can't concentrate or finish my cataloguing, and I don't have time to write more eloquent prose. If nothing else, think of the loss to great literature!",starts={{npcID=201291,x=0.344,y=0.592,zoneID=14433}},ends={{npcID=201291,x=0.344,y=0.592,zoneID=14433}},coords={x=0.344,y=0.592,source="quest_giver",zoneID=14433},questType="standard"},
[75026] = {id=75026,name="Up to the Highest Height!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Tuskarr children sure do love kites! I've seen some of them running around with them outside Morqut Village. I've also seen a lot of those kites stuck in trees. Can you do me a favor? Could you lasso some of those kites and pull them down? They'll probably fall down in pieces, but the children can always put their kites back together. Who knows? Maybe it will teach them to be more careful.",starts={{npcID=200558,x=0.344,y=0.586,zoneID=14433}},ends={{npcID=200558,x=0.344,y=0.586,zoneID=14433}},coords={x=0.344,y=0.586,source="quest_giver",zoneID=14433},questType="standard"},
[75050] = {id=75050,name="An Eclectic Accord",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="While the storm over the Reach was raging, I gathered allies for our eventual return. I want to ensure they have everything they need, but I can't welcome all of them personally. Would you be my envoy, ? Can you make sure they have what they need? We have few supplies to offer and a shortage of assistance. The least I can do is offer my gratitude. Please thank them personally on my behalf.",starts={{npcID=199201,x=0.346,y=0.576,zoneID=14433}},ends={{npcID=199201,x=0.346,y=0.576,zoneID=14433}},coords={x=0.346,y=0.576,source="quest_giver",zoneID=14433},questType="standard"},
[75154] = {id=75154,name="Waygate: Morqut Islet",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="We have access tae The Forbidden Reach now, and Cataloger Daela is already waitin' fer ya there. She's sent me a word of a very promising spire not far from the village where she's stayin'. Think there might be another dormant Waygate around? Go on an' find out!",starts={{npcID=189066,x=0.472,y=0.902,mapID=2022}},ends={{npcID=189066,x=0.472,y=0.902,mapID=2022}},coords={x=0.472,y=0.902,source="quest_giver",mapID=2022},questType="standard"},
