[75203] = {id=75203,name="Absent Friends",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=13862,mapID=2112,description="I am concerned about our queen. Alexstrasza left to gather her thoughts some time ago and has not yet returned. I have no real cause for concern, but with all that has happened, I cannot help but fear for her well-being. Please ease an old dragon's mind and ensure she is alright.",questType="standard"},
[75223] = {id=75223,name="Warcraft Rumble Minis: New Look!",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=13862,mapID=2112,description="This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!",ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},questType="standard"},
[75237] = {id=75237,name="Reach West",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? I heard the windstreams in the western Forbidden Reach are especially good today. Why don't you try a few courses out there?",starts={{npcID=200563,x=0.34,y=0.598,zoneID=14433}},ends={{npcID=200563,x=0.34,y=0.598,zoneID=14433}},coords={x=0.34,y=0.598,source="quest_giver",zoneID=14433},questType="standard"},
