[76164] = {id=76164,name="Bovan's Last Hope",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13645,mapID=2023,description="If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot. We still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work. Go to the Ohn'iri Springs and look for Boku. I'm sure he will help us. Baine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.",questType="standard"},
[76167] = {id=76167,name="A Place of Refuge",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13645,mapID=2023,description="Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. , I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.",questType="standard"},
[76168] = {id=76168,name="A Place of Refuge",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13645,mapID=2023,description="Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. , I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.",questType="standard"},
[76214] = {id=76214,name="Work It",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The Trial of Style gives us the opportunity to look good, . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",starts={{npcID=205914,x=0.542,y=0.598,mapID=2112}},ends={{npcID=205914,x=0.542,y=0.598,mapID=2112}},coords={x=0.542,y=0.598,source="quest_giver",mapID=2112},questType="standard"},
[76241] = {id=76241,name="Lab Partners with a Squirrel",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="I have finally brought history itself to life! I am a success! Now let's utilize your particular set of skills. Chiefly, I require your ability to go outside without dying of fright. Channeling my magic onto our new friend here, I'll teleport it to the location with the highest concentration of resonant energy linked to the relic. You'll meet up with it there and await further instructions. Fear not! My magics may elude your understanding, but my intellect is certain to guide us true!",starts={{npcID=205967,x=0.584,y=0.368,mapID=2025}},ends={{npcID=205975,x=0.584,y=0.368,mapID=2025},{npcID=205975,x=0.536,y=0.476,zoneID=14433}},coords={x=0.584,y=0.368,source="quest_giver",zoneID=13647},questType="standard"},
[76242] = {id=76242,name="A Research Thesis Worth Publishing",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Reese here is hungry as a dragon-horse for clues. Clues of the past! More specifically, we're going to use my unique brand of magic to unveil and analyze energy that resonates with the same frequency as our relic. You will guide Reese to these \"clues,\" where I will use him as a remote conduit to absorb those energies. When we've reached our critter's capacity to hold those energies, I'll port him back here to transmute it all into cold, hard data. Reese winks at you. How strange...>",starts={{npcID=205975,x=0.584,y=0.368,mapID=2025},{npcID=205975,x=0.536,y=0.476,zoneID=14433}},ends={{npcID=205967,x=0.584,y=0.368,mapID=2025}},coords={x=0.584,y=0.368,source="quest_giver",zoneID=13647},questType="standard"},
[76274] = {id=76274,name="Work It",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14433,description="The Trial of Style gives us the opportunity to look good, . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",starts={{npcID=206196,x=0.362,y=0.576,zoneID=14433}},ends={{npcID=206196,x=0.362,y=0.576,zoneID=14433}},coords={x=0.362,y=0.576,source="quest_giver",zoneID=14433},questType="standard"},
[76287] = {id=76287,name="Work It",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14433,description="The Trial of Style gives us the opportunity to look good, . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",starts={{npcID=206205,x=0.632,y=0.512,zoneID=14433}},ends={{npcID=206205,x=0.632,y=0.512,zoneID=14433}},coords={x=0.632,y=0.512,source="quest_giver",zoneID=14433},questType="standard"},
[76290] = {id=76290,name="Omarion's Second Handbook",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=139,mapID=23,description="Wilhelm, If you are reading this, the first adventurer I sent to you has perished. As have I, finally. I want you to know that my dying thoughts revolved around you and your ineptitude in tradeskills. About the book: These are the rest of my recipes. Please share them with someone more capable. Alas, I am sure you will keep them for yourself and charge a hefty fee for your services because you are, after all, a bastard. In Disdain, Omarion",questType="standard"},
[76368] = {id=76368,name="Ztest",level=0,requiredLevel=0,faction="none",expansion=10,zoneID=13862,mapID=2112,description="description",questType="standard"},
[76394] = {id=76394,name="Shadows of Flavor",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I've set out to create a meal that transcends the ordinary, one that even the emperor wouldn't turn away. I require ingredients from the darkest of shadows to craft this extraordinary meal. Many consider these ingredients forbidden, but they will become a harmony of light and shadow in my hands. Please assist me by harvesting the following ingredients: Shadowblind Grouper , Dark-Nurtured Scallions , and a Vial of Twilight Spice .",starts={{npcID=206533,x=0.644,y=0.31,mapID=2215}},ends={{npcID=206533,x=0.644,y=0.31,mapID=2215}},coords={x=0.644,y=0.31,source="quest_giver",mapID=2215},questType="standard"},
[76427] = {id=76427,name="A Dark Summons",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Denizens of Azeroth, Do you thirst for power? Do you wish to change your circumstances, to become... more? More free. More respected. More feared. Do you wish to become a Warlock? If your response to any of the above is \"yes\", then meet with my humble servant Phineas. In temptation, Madam Shadow",questType="standard"},
[76448] = {id=76448,name="The Fate of Scalecommander Abereth",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="According to our colleagues, this cave was used to test prospective scalecommanders. Excuse me. It either tested them or housed their remains. The trials were so difficult that it usually amounted to the same thing. We're searching for an ancient scalecommander referenced in our records as \"The Cleaving Blade\": a promising young dracthyr whose future ended abruptly somewhere near this cave. Perhaps we'll discover how their story ends.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.77,y=0.384,source="quest_giver",zoneID=14433},questType="standard"},
[76554] = {id=76554,name="Torch - 01",level=0,requiredLevel=0,faction="none",expansion=10,zoneID=13862,mapID=2112,description="description",questType="standard"},
[76557] = {id=76557,name="Without Honor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Ok, the goggles should be calibrated. Looks like the confluence point is right here on the ledge. I wonder what happened to him?",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.77,y=0.384,source="quest_giver",zoneID=14433},questType="standard"},
[76578] = {id=76578,name="Khaz Algar Rally",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[76592] = {id=76592,name="A Single Wing",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Amythora has returned with grave news. The Sundered Flame live on! We have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. And they have captured Marithos! Given that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.",starts={{npcID=207790,x=0.232,y=0.372,mapID=2112}},ends={{npcID=208236,x=0.74,y=0.548,mapID=2024}},coords={x=0.232,y=0.372,source="quest_giver",mapID=2024},questType="standard"},
[76735] = {id=76735,name="Rise in Relic Theft",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[76983] = {id=76983,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[76984] = {id=76984,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[76985] = {id=76985,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[77100] = {id=77100,name="Surveying the Cliffside",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Nothing like brisk ocean air to get you in the mood to dig! We're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters. If there's anything left that hasn't fallen into the sea, we'll find it!",starts={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},ends={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},coords={x=0.172,y=0.164,source="quest_giver",zoneID=14433},questType="standard"},
[77101] = {id=77101,name="Ingredient Quest Template",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,description="Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!",questType="standard"},
[77151] = {id=77151,name="The Cache in the Crag",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,ends={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},questType="standard"},
[77154] = {id=77154,name="A Taste of the Past",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel. That said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find. I'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?",starts={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},ends={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},coords={x=0.142,y=0.148,source="quest_giver",zoneID=14433},questType="standard"},
[77165] = {id=77165,name="A Secretive Contact",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=207696,x=0.478,y=0.47,mapID=2112}},ends={{npcID=207696,x=0.478,y=0.47,mapID=2112}},coords={x=0.478,y=0.47,source="quest_giver",mapID=2112},questType="standard"},
