[77415] = {id=77415,name="The Hidden Hand",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="Catching him at the very moment he's alone? They must've been watching somewhere nearby but just out of sight. Can you check that cave across the water? Those hornswogs are known hoarders. If those drakonid left something behind, it may still be there.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.77,y=0.384,source="quest_giver",zoneID=14433},questType="standard"},
