[77483] = {id=77483,name="Technoscrying: Dragonskull Island",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="I tuned my various sensors for Dracthyr relics, and they've triangulated a new location for us to investigate off the eastern coast of the Forbidden Reach. The local Drakonid tell me it's named Dragonskull Island. Ominous, no? You're not easily frightened, are you?",starts={{npcID=208355,x=0.618,y=0.298,mapID=2025}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.618,y=0.298,source="quest_giver",zoneID=13647},questType="standard"},
[77485] = {id=77485,name="Technoscrying: Back to Eadweard!",level=70,requiredLevel=70,faction="none",expansion=10,description="Thanks for all your help! Let's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.",questType="standard"},
[77487] = {id=77487,name="Excavation: Winglord's Perch",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,description="We've discovered an ancient fishing village in the Forbidden Reach! It's this humble isle off the northwest coast with its own crumbling bridge and everything! I'll be there if you're looking for more dirt to dig up!",starts={{npcID=208614,x=0.616,y=0.31,mapID=2025}},ends={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},coords={x=0.616,y=0.31,source="quest_giver",zoneID=13647},questType="standard"},
[77488] = {id=77488,name="Excavation: Back to Eadweard!",level=70,requiredLevel=70,faction="none",expansion=10,description="Great job, ! We've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!",questType="standard"},
