[77815] = {id=77815,name="The Storm Race Tour",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration. But since you are here, let us test its training--and your riding skills. My colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\". Fortune favors the bold, $p. Good luck!",starts={{npcID=193359,x=0.752,y=0.55,mapID=2022}},ends={{npcID=193359,x=0.752,y=0.55,mapID=2022}},coords={x=0.752,y=0.55,source="quest_giver",mapID=2022},questType="standard"},
[77832] = {id=77832,name="Shadows upon shadows",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14023,description="I need to save him.",questType="standard"},
