[77937] = {id=77937,name="Forbidden Sugar",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies. To the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver. However, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.",starts={{npcID=210162,x=0.368,y=0.628,mapID=2112}},ends={{npcID=210162,x=0.368,y=0.628,mapID=2112}},coords={x=0.368,y=0.628,source="quest_giver",mapID=2112},questType="standard"},
