[78228] = {id=78228,name="Into a Skittering City",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however... Nevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive. Perhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.",questType="standard"},
[78272] = {id=78272,name="Interrupting Duck",level=1,requiredLevel=1,faction="alliance",expansion=10,description="There are so many bunches of baby bunnies bouncing all about! Ducks have been swarming us and we haven't been able to feed the newborns. You look like you could handle the situation--care to help?",questType="standard"},
