[78717] = {id=78717,name="A Mysterious Warning",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin. I saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us. That's what we need to protect.",questType="standard"},
[78718] = {id=78718,name="Strengthen the Wards",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst. Here, take this wand. It's been attuned with Dalaran 's defense magics. Just wave it near strategic parts of the city to strengthen our magical defenses.",questType="standard"},
[78719] = {id=78719,name="Citizens of Dalaran",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Our citizens must be prepared for Dalaran 's departure. Can you ask around the city and see if anyone requires aid? I'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.",questType="standard"},
[78721] = {id=78721,name="Meet the Team",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. They're calling themselves the Algari Expedition this time around. I'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?",questType="standard"},
[78722] = {id=78722,name="To Khaz Algar!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out. Let me know when you're ready to depart.",ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},questType="standard"},
[78763] = {id=78763,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
