[78827] = {id=78827,name="Go Take Candle!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Ksk, ksk! You there! Yes, you! We, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me. Bring us, me, bring me candles ! Yes! No ask question, just go get candles . We are, er, I am professional, yes. Professionals do not ask questions. Only get candles .",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78860] = {id=78860,name="More Candles!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I, er, we...no, no, I! I have new deal for you, oh shadowy one. More candles ! In return, you get... er... You get more candles ! Then you give to us! To me! candles ! candles ! candles !",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78861] = {id=78861,name="Aiding the Accord",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[78893] = {id=78893,name="A Scrap of Bronze",level=10,requiredLevel=10,faction="none",expansion=10,description="The vendors of Pandaria do not want the equipment you will find in this timeline. You can convert unwanted equipment into Bronze using the magic of the infinite dragonflight. Use the Unraveling Sands ability and scrap the Unraveling Tunic .",questType="standard"},
[79006] = {id=79006,name="Faction Switch",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14663,description="Default",questType="standard"},
[79009] = {id=79009,name="The Harbinger",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.",questType="standard"},
[79085] = {id=79085,name="A Pile of Fish",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[79087] = {id=79087,name="A Pile of Clams",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[79105] = {id=79105,name="Breach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. Rescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.",starts={{npcID=214908,x=0.502,y=0.504,mapID=2305}},ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},coords={x=0.502,y=0.504,source="quest_giver",mapID=2305},questType="standard"},
[79106] = {id=79106,name="Rupture",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="Follow me. We'll work together to find any others in need of rescuing.",questType="standard"},
[79111] = {id=79111,name="Missing Lynx",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79115] = {id=79115,name="Expert Consultant",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight. The niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead. Go and barter with the rats. Come back with able bodies.",starts={{npcID=214356,x=0.75,y=0.808,mapID=2255}},ends={{npcID=215037,x=0.772,y=0.644,mapID=2255}},coords={x=0.75,y=0.808,source="quest_giver",mapID=2255},questType="standard"},
[79186] = {id=79186,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!",questType="standard"},
[79189] = {id=79189,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="\"Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!",questType="standard"},
[79199] = {id=79199,name="Renowned with Keg Leg's Crew",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13644,mapID=2022,description="Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.",questType="standard"},
[79231] = {id=79231,name="Back to Headquarters! Again!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist. Meet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433},{npcID=208362,x=0.172,y=0.164,zoneID=14433},{npcID=207763,x=0.382,y=0.498,mapID=2133},{npcID=208055,x=0.476,y=0.486,mapID=2133}},ends={{npcID=206107,x=0.614,y=0.312,mapID=2025}},coords={x=0.77,y=0.384,source="quest_giver",mapID=2025},questType="standard"},
[79245] = {id=79245,name="[Unused - Reuse Quest Bit]",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79350] = {id=79350,name="Intro Dummy Quest Week 1 (Text Only)",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79523] = {id=79523,name="Something Hidden",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing. Excellent work, ! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence. Smash the bottoms out of the crates and bring anything you find back to me.",starts={{npcID=219394,x=0.498,y=0.494,mapID=2339}},ends={{npcID=219394,x=0.498,y=0.494,mapID=2339}},coords={x=0.498,y=0.494,source="quest_giver",mapID=2339},questType="standard"},
[79655] = {id=79655,name="Hallowfall Arathi",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79659] = {id=79659,name="The Severed Threads",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79955] = {id=79955,name="...And Now I'm Arachnophobic",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Who is there? Someone? Did I imagine you? I am Albert . I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts. My eyes. My insides. It hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. I wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?",questType="standard"},
[79956] = {id=79956,name="Legs in the Ceiling",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach. The horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!",questType="standard"},
[79999] = {id=79999,name="Igniting Hope",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. The shattered remnants needed to sustain that light were taken by the nerubians. Gather the remnants from nerubians you slay, and help ignite a beacon of hope!",starts={{npcID=213116,x=0.684,y=0.45,mapID=2215}},ends={{npcID=213116,x=0.684,y=0.45,mapID=2215}},coords={x=0.684,y=0.45,source="quest_giver",mapID=2215},questType="standard"},
[80145] = {id=80145,name="The Motherlode",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=230643,x=0.048,y=0.796,mapID=2214}},ends={{npcID=230643,x=0.048,y=0.796,mapID=2214}},coords={x=0.048,y=0.796,source="quest_giver",mapID=2214},questType="standard"},
[80196] = {id=80196,name="Extract a Gem",level=10,requiredLevel=10,faction="none",expansion=10,description="Any gem can be removed from your equipment using the Extract Gem ability. The gem will not be destroyed. Extract a gem now.",questType="standard"},
[80197] = {id=80197,name="Combine Gems",level=10,requiredLevel=10,faction="none",expansion=10,description="Prismatic gems can be combined to create a more powerful gem. Combine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.",questType="standard"},
