[80321] = {id=80321,name="Departure",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="Best if we split up here. I'll guide everyone to safety and see about getting them evacuated. In the meantime, you should search for Khadgar. I'm sure he could use your aid as well. You'll find another exit further ahead that should lead back to the surface.",questType="standard"},
[80389] = {id=80389,name="Last Hurrah",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=13862,mapID=2112,questType="standard"},
[80397] = {id=80397,name="Sweets Seekers",level=73,requiredLevel=73,faction="none",expansion=10,zoneID=14795,mapID=2214,description="Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it! As I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.",questType="standard"},
[80500] = {id=80500,name="The Bronzebeard Family",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="We need to let Brann and my son Dagran know what happened. They're at Dalaran 's visitor center. Could ye go get them for me? Father needs his family right now.",questType="standard"},
[80512] = {id=80512,name="Beat the Best",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="If Glumtooth Gang succeed, this earthen first captive of many. We need free him. He prize. Every kobold here want fight him. Must earn our place. You beat up strong bugs, they think me strong trainer. Then they let you into ring. May best bug win.",questType="standard"},
[80513] = {id=80513,name="Snouty Sabotage",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both. Some fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape. While you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.",questType="standard"},
[80562] = {id=80562,name="Blossoming Delight",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Few followers of the light would dare to attempt the dish I plan to make. A mix of traditional Imperial spices combined with the forbidden harvest of the nearby fungal blooms. This dish will delight the palate and remind one of the adventurous spirit that founded the Hallowfall expedition. Please journey to the Mycomancer Cavern nearby and harvest the blooms I require.",starts={{npcID=206533,x=0.644,y=0.31,mapID=2215}},ends={{npcID=206533,x=0.644,y=0.31,mapID=2215}},coords={x=0.644,y=0.31,source="quest_giver",mapID=2215},questType="standard"},
[80568] = {id=80568,name="Leave No Trace",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I need to go make sure she's all right. What I saw in that cave... If she's more sensitive to this... Hannan nearly growls.> But she's making a mess out here, drawing attention and leaving a trail leading outsiders right to her! Right to us. We're supposed to be subtle. Unseen. Keep to the brush, hide in our other forms as much as possible. I hate to ask this of you, but can you use my scythe to take care of the evidence while I check on her?",starts={{npcID=223286,x=0.598,y=0.64,mapID=2255}},ends={{npcID=227158,x=0.624,y=0.79,mapID=2255}},coords={x=0.598,y=0.64,source="quest_giver",mapID=2255},questType="standard"},
[80569] = {id=80569,name="Harmonious Approach",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I know I cannot stop Orweyna from going down there and drawing attention to our presence. But... perhaps we could stop word of our presence from spreading. Find whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.",questType="standard"},
[80570] = {id=80570,name="Staunch the Flow",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Do they even understand what they are doing? Orweyna bares her teeth, practically growling.> Destroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage. We cannot stop them all, not today. But a bit of destruction may temper my rage.",questType="standard"},
[80571] = {id=80571,name="Decipher the Cacophony",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder... Orweyna seems shaken, but not deterred.> I can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is. . Bring me something from the Unseeming.",questType="standard"},
[80572] = {id=80572,name="Discordant Measures",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I cannot stand to look at this any longer. I must act. . You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed. We will kill what we can and search for some sliver of hope that we can still restore this land.",questType="standard"},
[80680] = {id=80680,name="Tarnished Compass",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=439890,x=0.435,y=0.517,mapID=2215}},ends={{npcID=439890,x=0.435,y=0.517,mapID=2215}},coords={x=0.435,y=0.517,source="quest_giver",mapID=2215},questType="standard"},
