[81670] = {id=81670,name="Shattered Silk",level=78,requiredLevel=78,faction="none",expansion=10,zoneID=14752,mapID=2255,description="Nothing will get the attention of the Head Cutter--and disrupt her operations--like destroying her equipment! Get in there and mess stuff up, really send a message.",questType="standard"},
