[81908] = {id=81908,name="A Flame in the Dark",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid. This item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians. Your task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.",questType="standard"},
[81966] = {id=81966,name="Slept Like a Rock",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Champion, Da's awake. Please return to Dalaran .",questType="standard"},
[81976] = {id=81976,name="Bazaar, Isn't It?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,starts={{npcID=222186,x=0.286,y=0.14,mapID=371}},ends={{npcID=222186,x=0.286,y=0.14,mapID=371}},coords={x=0.286,y=0.14,source="quest_giver",mapID=371},questType="standard"},
[81985] = {id=81985,name="Worldsoul Memory: The Worldcarvers",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[82126] = {id=82126,name="Defense of the People",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,mapID=2213,description="The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. But whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned! We must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.",questType="standard"},
[82127] = {id=82127,name="Make Them Prey",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,mapID=2213,description="These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. They stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in. Hunt these abductors down and show them who is really the prey.",questType="standard"},
