[82195] = {id=82195,name="Rust and Redemption",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="As you approach, a rusty lever catches your eye, stubbornly stuck in its place. \"This thing hasn't moved in ages,\" you muse, as you feel the rough metal resist your touch. Glancing around, you note the oily sheen on the plantlike Crawlers. \"Perhaps a bit of natural lubricant would do the trick,\" you ponder, realizing that these flora foes might yield what you need to ease the lever's grip.",starts={{npcID=443532,x=0.534,y=0.446,mapID=2214}},ends={{npcID=443532,x=0.534,y=0.446,mapID=2214}},coords={x=0.534,y=0.446,source="quest_giver",mapID=2214},questType="standard"},
