[82340] = {id=82340,name="Loss of Limb",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Happy greetings! I am Mr. Sunflower , and this is my tea room and therapy space. It is a safe place for everyone! I wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. Would you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?",questType="standard"},
