[82486] = {id=82486,name="Worldsoul: The Rookery",level=70,requiredLevel=70,faction="none",expansion=10,description="The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, .",questType="standard"},
[82488] = {id=82488,name="Worldsoul: Darkflame Cleft",level=70,requiredLevel=70,faction="none",expansion=10,description="Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!",questType="standard"},
[82490] = {id=82490,name="Worldsoul: Priory of the Sacred Flame",level=70,requiredLevel=70,faction="none",expansion=10,description="My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, . Stop them.",questType="standard"},
[82498] = {id=82498,name="Worldsoul: Darkflame Cleft",level=70,requiredLevel=70,faction="none",expansion=10,description="Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!",questType="standard"},
[82499] = {id=82499,name="Worldsoul: Priory of the Sacred Flame",level=70,requiredLevel=70,faction="none",expansion=10,description="My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, . Stop them.",questType="standard"},
[82500] = {id=82500,name="Worldsoul: The Rookery",level=70,requiredLevel=70,faction="none",expansion=10,description="The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, .",questType="standard"},
[82501] = {id=82501,name="Worldsoul: The Dawnbreaker",level=70,requiredLevel=70,faction="none",expansion=10,description="The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. It is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.",questType="standard"},
[82502] = {id=82502,name="Worldsoul: Ara-Kara, City of Echoes",level=70,requiredLevel=70,faction="none",expansion=10,description="Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. There's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. We need to find out what's going on. Bring together your strongest companions and investigate!",questType="standard"},
[82503] = {id=82503,name="Worldsoul: Cinderbrew Meadery",level=70,requiredLevel=70,faction="none",expansion=10,description="Ah, Cinderbrew. It really is as stout and fiery a brew as they claim. I can't help but imagine it's how Beledar would taste... The earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands. But... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.",questType="standard"},
[82504] = {id=82504,name="Worldsoul: City of Threads",level=70,requiredLevel=70,faction="none",expansion=10,description="Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. We must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!",questType="standard"},
[82505] = {id=82505,name="Worldsoul: The Stonevault",level=70,requiredLevel=70,faction="none",expansion=10,description="Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. I can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. Eirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!",questType="standard"},
[82506] = {id=82506,name="Worldsoul: Darkflame Cleft",level=70,requiredLevel=70,faction="none",expansion=10,description="Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!",questType="standard"},
[82507] = {id=82507,name="Worldsoul: Priory of the Sacred Flame",level=70,requiredLevel=70,faction="none",expansion=10,description="My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, . Stop them.",questType="standard"},
[82508] = {id=82508,name="Worldsoul: The Rookery",level=70,requiredLevel=70,faction="none",expansion=10,description="The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, .",questType="standard"},
[82509] = {id=82509,name="Worldsoul: Nerub-ar Palace",level=70,requiredLevel=70,faction="none",expansion=10,description="Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!",questType="standard"},
[82510] = {id=82510,name="Worldsoul: Nerub-ar Palace",level=70,requiredLevel=70,faction="none",expansion=10,description="Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!",questType="standard"},
[82539] = {id=82539,name="Radiant Echoes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="$p, please come to Dalaran at once. Strange phenomena are appearing all across Azeroth. We believe they may be connected to the Radiant Song. I'd like you to investigate.",questType="standard"},
[82540] = {id=82540,name="Memories of Adventures Past",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. Past events have now come to life once more. I believe they're Azeroth's memories. Memories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.",questType="standard"},
