[82629] = {id=82629,name="Nerub-ar Palace: For Nerubian Eyes Only",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14980,description="Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. Fetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.",questType="raid"},
[82638] = {id=82638,name="Nerub-ar Palace: For Nerubian Eyes Only",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14980,description="Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. Fetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.",questType="raid"},
