[82739] = {id=82739,name="Twilight Scheming",level=20,requiredLevel=20,faction="none",expansion=10,zoneID=1584,mapID=84,description="The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.",questType="dungeon"},
[82740] = {id=82740,name="Twilight Scheming",level=20,requiredLevel=20,faction="horde",expansion=10,zoneID=1584,mapID=84,description="The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.",questType="dungeon"},
