[83057] = {id=83057,name="Setting Boundaries",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe. Whenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this. But hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.",questType="standard"},
