[83326] = {id=83326,name="The Final Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You are good candle-taker. We have one last job for you, your waxiness! One more job! Then no more sticky business. BIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. Nothing rhymes with kobolds, hm. Get us big candle!",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
