[83486] = {id=83486,name="Remote Work",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,mapID=862,description="If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. If you're here to collect on a debt, you are TRESPASSING and must disregard this note . -Getry",starts={{npcID=454456,x=0.324,y=0.559,mapID=2346}},ends={{npcID=466110,x=0.209,y=0.588,mapID=862}},coords={x=0.324,y=0.559,source="quest_giver",mapID=862},questType="standard"},
[83521] = {id=83521,name="Little Help, Please?",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,description="So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light. I just got that fixed. I swear it! Would you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it. Shouldn't be more than a minute. Two at most!",questType="standard"},
[83547] = {id=83547,name="Welcome to the Neighborhood",level=0,requiredLevel=0,faction="none",expansion=10,zoneID=6170,mapID=37,description="Welcome to Borogrove, ! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood. Once you've settled in, please come see me at Town Hall.",questType="standard"},
