[84582] = {id=84582,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14752,mapID=2255,starts={{npcID=464929,x=0.568,y=0.391,mapID=2255}},ends={{npcID=464929,x=0.568,y=0.391,mapID=2255}},coords={x=0.568,y=0.391,source="quest_giver",mapID=2255},questType="standard"},
[84639] = {id=84639,name="Torches and Tar",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="We've been attacked before. But this time... This was different. They didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs. I don't know what they're going to do with it, but... I can guess. They're going to burn something down. You need to stop them before they do another homestead harm!",questType="standard"},
[84640] = {id=84640,name="Emblematic of Things to Come",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="unfamiliar emblem . The emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red. Perhaps Danath can identify it.>",questType="standard"},
[84641] = {id=84641,name="Ill Tidings",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands... Stromgarde was right to send a missive asking for my return. What is going on here? I placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.",questType="standard"},
[84643] = {id=84643,name="Curfew Kerfuffle",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order. Marran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it. As my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.",questType="standard"},
[84645] = {id=84645,name="Deputy Delivery",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks. Nials was too busy, so I took it upon myself to write official requests for aid. Most are simple and straightforward--writs for supplies and such for the Stromic army. The desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot. As my deputies, would you enforce my requests for aid?",questType="standard"},
[84649] = {id=84649,name="Marran Trollbane",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I am Colonel Veronica Nials , and I am in command of Stromgarde in Lord Trollbane's absence. I'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. Her actions during his absence led him to imprison her when he returned. That said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.",questType="standard"},
[84650] = {id=84650,name="Finding Refuge at Refuge Pointe",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here. He may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there. You might catch up with him there.",questType="standard"},
[84651] = {id=84651,name="A Familiar Face",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources. Now they are better coordinated. As if they are working together as a group. That's bad news for everyone. But rivals don't come together without a strong leader. And without them, they will fall. If you're willing, find the leader of this attack on Refuge Pointe and eliminate them.",questType="standard"},
[84652] = {id=84652,name="Supply Run",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. Hammerfall does what it can to help, but we too fight in Khaz Algar. We've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources. But there may be a way to help more people. Vikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.",questType="standard"},
[84653] = {id=84653,name="DEPRECATED",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15716,mapID=14,questType="standard"},
[84656] = {id=84656,name="Onward to Hammerfall",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. Different groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. Also, Joseph is directly involved. This all seems connected... and it leads back to Marran. Danath needs to know what's going on. If he's not here, he should already be at Hammerfall. We should head there as soon as possible.",questType="standard"},
[84657] = {id=84657,name="Return to Stromgarde",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance. We need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search! Come, . There's no time to waste!",questType="standard"},
[84658] = {id=84658,name="Finding Family",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Where's my mama? My papa? Ellie ? I was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here. I don't know where Mama and Papa and Ellie are. Can you find them for us? Clarabelle is starting to get worried...",questType="standard"},
[84659] = {id=84659,name="The Search for Faerin",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building. Go find her. Hopefully, she's still alive... And see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere. The more information we have, the more we can use against them when we fight back.",questType="standard"},
[84704] = {id=84704,name="A Different Point of View",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Danath is not here. Faerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. I will dispatch outriders immediately to search for him. While we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them. Distribute the crates directly to them. I'm sure they will be grateful for the food inside.",questType="standard"},
[84705] = {id=84705,name="Withering the Witherbark",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="The Witherbark have always been an annoyance since I have been here. But now? Something has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame. Eitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. But we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders! Make them think twice about that.",questType="standard"},
[84706] = {id=84706,name="Crime Family",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. But he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks. He has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.",questType="standard"},
[84707] = {id=84707,name="To See a Troll",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. I have told him we would go and give her the news. She's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. I can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde. Let's go. We can look for Danath while we're out there.",questType="standard"},
[84708] = {id=84708,name="The Syndicate Strikes Back",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended! Let's go . We must defend our home!",questType="standard"},
[84709] = {id=84709,name="Hammerfall Down",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Eitrigg growls in frustration.> I was such a fool! I should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall. And were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides... But now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. Those spies have had enough of my open hand. Now they'll suffer my fists!",questType="standard"},
[84710] = {id=84710,name="Once Bitten Twice Shy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="I caught a glimpse of who was leading the attack. It looks like Joseph the Enlightened may be less full of hot air than we thought he was. Is he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.",questType="standard"},
[84711] = {id=84711,name="Danath's Disappearance",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="My outriders discovered a destroyed caravan on the road. Around it were the bodies of Stromic soldiers. It could be Danath's escort. Or it could be another hapless group. Either way, we must investigate. Let us hope Danath is not among the dead.",questType="standard"},
[84712] = {id=84712,name="False Flag",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently. If Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable. We must search for Danath among the dead and find out what happened here. Leave no stone left unturned.",questType="standard"},
[84713] = {id=84713,name="Fallen Fortress",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="If Danath's kidnappers want to keep him from prying eyes, Ar'gorok is the perfect place. It's been abandoned for years, but its buildings still stand. All the \"Red Dawn\" could be there and no one would be the wiser. We must find Danath quickly, $p. Hammerfall is vulnerable and tensions are high. A missing leader is just the excuse Marran needs to start a war.",questType="standard"},
[84714] = {id=84714,name="From Ironforge With Love",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner. And I'm sure they've brought their spoils with them. It may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands . See if they are carrying anything with them.",questType="standard"},
[84715] = {id=84715,name="The Search for Danath",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Using Ar'gorok as a base was clever. Very clever. It looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here. Search the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. Let's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.",questType="standard"},
[84716] = {id=84716,name="Returning to Stromgarde",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde. My kidnapping was just the start. Colonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup! Marran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\" We must gather our allies... and confront these traitors!",questType="standard"},
[84717] = {id=84717,name="Rise of the Red Dawn",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed. But after seeing Joseph the Enlightened 's handiwork first hand... Despite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down. He's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.",questType="standard"},
[84781] = {id=84781,name="Master of Secrets",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=6757,mapID=554,questType="standard"},
[84784] = {id=84784,name="Lorewalking: The Blade's Nemeses",level=10,requiredLevel=10,faction="both",expansion=10,description="Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive. You know what to do.",questType="standard"},
[84787] = {id=84787,name="The Drain",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
[84835] = {id=84835,name="The Drowned Lair",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
[84836] = {id=84836,name="Shuddering Hollow",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
[84894] = {id=84894,name="G.E.T.A. 2",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[84914] = {id=84914,name="Valorstones",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=223726,x=0.392,y=0.24,mapID=2339}},ends={{npcID=223726,x=0.392,y=0.24,mapID=2339},{npcID=221390,x=0.472,y=0.328,mapID=2214}},coords={x=0.392,y=0.24,source="quest_giver",mapID=2214},questType="standard"},
[84934] = {id=84934,name="A Dark Descent",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[84965] = {id=84965,name="Core Contributions",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="The entropic cores we collected will be crucial in our defense. Use the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders. Time is of the essence, . The fate of Tazavesh rests in your hands.",starts={{npcID=234483,x=0.375,y=0.399,mapID=2472}},ends={{npcID=234483,x=0.375,y=0.399,mapID=2472}},coords={x=0.375,y=0.399,source="quest_giver",mapID=2472},questType="standard"},
[84993] = {id=84993,name="Devourer Attack: The Oasis",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,questType="standard"},
[85029] = {id=85029,name="Lorewalking: Locus-Walker",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=2393,description="While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. Not just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power. But there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.",questType="standard"},
[85044] = {id=85044,name="DEPRECATED",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[85047] = {id=85047,name="A Pirate Predicament",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north. Pirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?",starts={{npcID=232405,x=0.63,y=0.502,mapID=71},{npcID=232406,x=0.63,y=0.502,mapID=71},{npcID=232407,x=0.63,y=0.502,mapID=71},{npcID=232408,x=0.63,y=0.502,mapID=71}},ends={{npcID=231413,x=0.608,y=0.448,mapID=71}},coords={x=0.63,y=0.502,source="quest_giver",mapID=71},questType="standard"},
[85071] = {id=85071,name="Skyrocketing Sprint",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85096] = {id=85096,name="Skyrocketing Sprint - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85097] = {id=85097,name="The Heaps Leap",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85098] = {id=85098,name="The Heaps Leap - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85099] = {id=85099,name="Scrapshop Shot",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85100] = {id=85100,name="Scrapshop Shot - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85101] = {id=85101,name="Rags to Riches Rush",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85102] = {id=85102,name="Rags to Riches Rush - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85451] = {id=85451,name="The Burning of Hammerfall",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="The Syndicate has put Hammerfall to torch! And the cowards are using pyromancers to feed the flames. But we can save our huts if we get to them quickly. Fight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!",questType="standard"},
[85460] = {id=85460,name="Ecological Succession",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15336,mapID=2371,questType="world"},
[85471] = {id=85471,name="Renowned with the Gallagio Loyalty Rewards Club",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="The Gallagio appreciates your continued loyalty! We've got some extra supplies for only our most honored of High Rollers. Come see us for your gift!",ends={{npcID=235617,zoneID=15522}},questType="standard"},
[85529] = {id=85529,name="Past Glory",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Marran's\"Red Dawn\" has left the city and peace has returned to Stromgarde. At least for now. Faerin left for the countryside. She said she wanted to check on Newstead and Refuge Point, but I think she wanted to get out of Stromgarde. She came here with such enthusiasm. I should not have tempered it so harshly. I feel in the end it was I who needed to learn a lesson. We should check in on her.",questType="standard"},
[85531] = {id=85531,name="Earth-Encrusted Gem",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2255,starts={{npcID=223750,x=0.552,y=0.412,mapID=2255}},ends={{npcID=220867,x=0.552,y=0.412,mapID=2255},{npcID=223750,x=0.552,y=0.412,mapID=2255}},coords={x=0.552,y=0.412,source="quest_giver",mapID=2255},questType="standard"},
