[85678] = {id=85678,name="Repair Yourself",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=10424,mapID=1409,description="Your gear isn't looking too great from your last excursion. Speak to Quartermaster Richter to get it repaired.",starts={{npcID=156807,x=0.522,y=0.552,mapID=1409},{npcID=245394,x=0.522,y=0.556,mapID=1409}},ends={{npcID=156807,x=0.522,y=0.552,mapID=1409},{npcID=245394,x=0.522,y=0.556,mapID=1409}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
