[85862] = {id=85862,name="A Prince's Duty",level=10,requiredLevel=10,faction="both",expansion=10,description="It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything. It's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. Whip these troops into shape. No doubt Muradin has been itching for a brawl as well...",questType="standard"},
[85871] = {id=85871,name="Lorewalking: The Blade's Forces",level=10,requiredLevel=10,faction="both",expansion=10,description="Xal'atath brings with her an army of shadows and tricks. They are nothing to our evolved forms! You have been chosen--blessed with power by N'Zoth to serve as his champion. Go now and destroy them!",questType="standard"},
[85873] = {id=85873,name="Another Shadowy Invitation",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="$p, do you like paperwork and forms as much as I do? Then let us dispense with the expedited entry to Tazavesh and experience once more the joy of jumping through bureaucratic hoops and paying bribes as is the tradition of all great broker stories. WARNING! COMPLETING THIS QUEST WILL REQUIRE YOU TO FINISH CHAPTER 1 OF THE 11.2 CAMPAIGN!",questType="standard"},
