[85949] = {id=85949,name="A Frozen Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=4395,mapID=125,description="The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",questType="standard"},
[85953] = {id=85953,name="The Drag",level=50,requiredLevel=50,faction="none",expansion=10,zoneID=15946,questType="standard"},
[86151] = {id=86151,name="Faceless Mask of the Burned Bridge",level=80,requiredLevel=80,faction="both",expansion=10,description="The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.",questType="standard"},
[86152] = {id=86152,name="Faceless Mask of the Daredevil",level=80,requiredLevel=80,faction="both",expansion=10,description="The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.",questType="standard"},
[86153] = {id=86153,name="Faceless Mask of the Dark Imagination",level=80,requiredLevel=80,faction="both",expansion=10,description="These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.",questType="standard"},
[86154] = {id=86154,name="Faceless Mask of the Pained",level=80,requiredLevel=80,faction="both",expansion=10,description="Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.",questType="standard"},
[86155] = {id=86155,name="Faceless Mask of the Long Night",level=80,requiredLevel=80,faction="both",expansion=10,description="The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.",questType="standard"},
[86174] = {id=86174,name="Special Assignment: Storm's a Brewin",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
