[86469] = {id=86469,name="A Stromgarde Tour",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=16432,mapID=2451,questType="standard"},
[86470] = {id=86470,name="Fearin's Version",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15716,mapID=14,description="I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch. As my newest deputy, this responsibility is now yours! Most of these are simple and straightforward. Requests for supplies and such for the Stromic army. Joseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.",questType="standard"},
[86476] = {id=86476,name="Worldsoul Memory: Early Cartel Wars",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[86477] = {id=86477,name="Worldsoul Memory: Kaja'mite Contact",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[86479] = {id=86479,name="LFGDungeons - 11.0 The War Within - Raid Finder - 1st",level=30,requiredLevel=30,faction="none",expansion=10,questType="standard"},
[86481] = {id=86481,name="Short-Supply Reward",level=30,requiredLevel=30,faction="none",expansion=10,questType="standard"},
[86493] = {id=86493,name="LFGDungeons - Timewalking \"Heroic\" Random - 1st",level=0,requiredLevel=0,faction="none",expansion=10,questType="standard"},
[86555] = {id=86555,name="Undermine Benefactor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[86563] = {id=86563,name="A Savage Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=7333,description="The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",starts={{npcID=151955,x=0.37,y=0.724,zoneID=7332},{npcID=151987,x=0.428,y=0.544,zoneID=7333}},ends={{npcID=151955,x=0.37,y=0.724,zoneID=7332},{npcID=151987,x=0.428,y=0.544,zoneID=7333}},coords={x=0.37,y=0.724,source="quest_giver",zoneID=7332},questType="standard"},
[86564] = {id=86564,name="A Fel Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=7502,mapID=627,description="A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",questType="standard"},
[86619] = {id=86619,name="Theater Troupe",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[86801] = {id=86801,name="Faceless Mask of Multitudes",level=80,requiredLevel=80,faction="both",expansion=10,description="By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.",questType="standard"},
[86905] = {id=86905,name="No More Sick Days",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again? When you're done see my assistant for payment.",questType="standard"},
[86915] = {id=86915,name="Side with a Cartel",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86917] = {id=86917,name="Ship Right",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86918] = {id=86918,name="Reclaimed Scrap",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86919] = {id=86919,name="Side Gig",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86920] = {id=86920,name="War Mode Violence",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86921] = {id=86921,name="This is a repro test",level=0,requiredLevel=0,faction="none",expansion=10,questType="standard"},
[86923] = {id=86923,name="Go Fish",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86924] = {id=86924,name="Gotta Catch at Least a Few",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86936] = {id=86936,name="Warped Wood",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job. If you could clear out a few it would really help speed up our construction efforts.",questType="standard"},
[86937] = {id=86937,name="Healthy Home Certified",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources. Do us a favor and get rid of him? As always, see my assistant for payment.",questType="standard"},
[86960] = {id=86960,name="The Key to Good Health",level=70,requiredLevel=70,faction="none",expansion=10,description="I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?",questType="standard"},
[86962] = {id=86962,name="Blood in the Wound",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[86994] = {id=86994,name="LFGDungeons - 11.1 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[87000] = {id=87000,name="No Wood Left Behind",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.",questType="standard"},
[87284] = {id=87284,name="A Radiant Echo",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14771,mapID=2339,questType="standard"},
[87299] = {id=87299,name="How Old Are These Things?",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane. But when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies! Help us take out her goons and collect any evidence that shows what they really are!",questType="standard"},
[87302] = {id=87302,name="Rare Rivals",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87303] = {id=87303,name="Clean the Sidestreets",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
