[87305] = {id=87305,name="Desire to D.R.I.V.E.",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87306] = {id=87306,name="Kaja Cruising",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87307] = {id=87307,name="Garbage Day",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87374] = {id=87374,name="C.H.E.T.T.ing In",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Undermine with directions to The Incontinental's second floor.>",questType="standard"},
[87405] = {id=87405,name="Warrant: Grubber",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber. Tragically, we lost deputy Zo'wie when he went out to investigate. The creature pulled him under the sand. Devise a method to lure the worm into revealing itself, so it may be eliminated once and for all.",questType="standard"},
[88652] = {id=88652,name="Faceless Mask of the Nemesis",level=80,requiredLevel=80,faction="both",expansion=10,description="There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.",questType="standard"},
[88754] = {id=88754,name="Short-Supply",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[88803] = {id=88803,name="Timely Assistance",level=50,requiredLevel=50,faction="both",expansion=10,description="Hello, Champion. I have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass. I will form a construct that will assist you in the vision.",questType="standard"},
[88901] = {id=88901,name="Dastardly Duos Reward",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[88903] = {id=88903,name="Faceless Mask of Vengeance",level=80,requiredLevel=80,faction="both",expansion=10,description="Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.",questType="standard"},
[88970] = {id=88970,name="LFGDungeons - 11.2 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
