[89351] = {id=89351,name="Liberation of Undermine: Splitting Pairs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact. Mug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.",starts={{npcID=235619,zoneID=15522}},ends={{npcID=235619,zoneID=15522}},questType="raid"},
