[89404] = {id=89404,name="Time Crisis",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="You don't remember me? Hmmm, shifting through time can sometimes have that side-effect. Good thing I love introductions. Let me catch you up to speed on what we're doing here.",questType="standard"},
[89405] = {id=89405,name="Mean Streets of Dalaran",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="The rest of the Council and I are currently barricaded in the Chamber of the Guardian working on a solution. In the meantime, we could use your help by taking some of the Legion's attention off us so we have time to think. Once you've bought us enough time to properly assess the situation, join me in the Chamber of the Guardian so we can turn this situation around and put the Legion on the defensive.",questType="standard"},
[89406] = {id=89406,name="Seal and Protect",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="The citizens of Dalaran have sequestered themselves behind magical barriers that will keep the Legion at bay, for now. However, the power of the barriers is not infinite. Take my Reinforcing Ring and reinforce the barriers in order to keep our people safe. That will free me up to investigate the source of this Legion invasion. Once you're done, keep culling the Legion's numbers. I'll contact you once I've discovered more.",questType="standard"},
[89407] = {id=89407,name="Thrift",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="If we're going to help Khadgar, Dalaran, and our experiment, we're going to need to get you an artifact. Luckily I have a plan to accomplish just this. Dalaran is currently loaded with all manner of temporally important items--so called epoch objects. We'll gather up a few that won't be missed, blame their disappearance on the Legion, and then use them to get you that artifact. Here, I've made a shopping list.",questType="standard"},
[89408] = {id=89408,name="Threadbare",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="To get you an artifact we'll need some temporal energy. Normally we use infinite cloaks woven from temporal threads, but those threads are frayed in this timeline. So instead I need you to gather those frayed temporal threads from around Dalaran. You can find them popping into and out of existence here and there. They look like radiant golden orbs of power, you can't miss them. Once you have enough of them bring them back to me.",questType="standard"},
[89411] = {id=89411,name="Scavenger Hunting",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Momentus may be expert what makes things, but Erus be expert what break things! Erus energetically punches his fist into his palm to accentuate the word \"break\".> Go. Kill demons. Take their armor scraps. Then we get to scrapping! I love scrapping.",questType="standard"},
[89412] = {id=89412,name="Get Plenty of Exorcise",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Khadgar is close to divining the source of the Legion presence here, but there is no guarantee that he will if the Legion's plans proceed unchallenged. The fate of Dalaran is not yet decided. All he needs is a little more time. You can buy him that time by halting the Legion's efforts here in the city. Seek out Legion Portals and seal them. That should slow the arrival of more demons entering the city.",questType="standard"},
[89413] = {id=89413,name="Obliterate, Then Iterate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Artifact is not what catches eye of Erus . No. You have demon armor scraps. Now, you might think to yourself, 'but Erus , demon armor scraps are junk', and you might be right. But Erus sees demon scraps and he does not see junk, he sees bronze . bronze hidden in the junk. Listen closely, Erus will teach you how to use the Unraveling Sands. You put junk in sands, sands unravels it, and then you get bronze from the ashes. Try using the Unraveling Sands and then toss in the Legion armor scraps .",questType="standard"},
[89414] = {id=89414,name="Not A Memento Too Soon",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Everything is unfolding splendidly, . With your artifact in hand, you should have no issues assisting Khadgar in driving the Legion fully from Dalaran. According to Moratari's calculations, he should have discovered the source of the Legion invasion. Return to the Chamber of the Guardian when you are ready and learn what he has discovered.",questType="standard"},
[89415] = {id=89415,name="Storm the Citadel",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Fel Lord Nezmet managed to slip through our teleportation spell and open cracks within our wards. Left unopposed, Nezmet will widen those cracks until the wards fail and the full might of the Legion is brought down upon us. We have a chance now, to finish him before he finishes us. Cut off their head and the rest of the Legion will wither and die. Head to the Violet Citadel with all haste. There is not a moment to lose.",questType="standard"},
[89420] = {id=89420,name="Horrific Visions Revisited",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[89493] = {id=89493,name="Welcome to the Field",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=240852,x=0.282,y=0.562,mapID=2215}},ends={{npcID=240852,x=0.282,y=0.562,mapID=2215}},coords={x=0.282,y=0.562,source="quest_giver",mapID=2215},questType="standard"},
