[90659] = {id=90659,name="Something Borrowed",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them. No one will be the wiser. All we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out. Let's start by selecting your specialization, that'll determine which artifact we'll be borrowing.",questType="standard"},
