[90778] = {id=90778,name="Ancient Curiosity: Utility",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15329,mapID=2393,questType="standard"},
[90779] = {id=90779,name="Cracked Keystone",level=70,requiredLevel=70,faction="none",expansion=10,description="Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?",questType="standard"},
[90901] = {id=90901,name="As A Matter of Artifact",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="There's more to artifacts than meets the eye, . Simply using an artifact allows its legend to grow, and as that legend grows, so too does its power. In order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable. Let's get started.",questType="standard"},
[90970] = {id=90970,name="Titan Disc-Count",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=16427,description="We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. Make sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.",questType="standard"},
[90971] = {id=90971,name="Overcharged Console",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15329,mapID=2393,description="With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. Use the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.",questType="standard"},
[91041] = {id=91041,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
