[91614] = {id=91614,name="Focusing the Energies",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=7846,mapID=747,description="In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln. This rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.",starts={{npcID=103832,x=0.448,y=0.504,mapID=747}},ends={{npcID=101195,x=0.448,y=0.516,mapID=747}},coords={x=0.448,y=0.504,source="quest_giver",mapID=747},questType="standard"},
[91615] = {id=91615,name="A Thirst For Blood",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=7695,mapID=648,questType="standard"},
[91618] = {id=91618,name="A Few Things First",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=7502,mapID=627,description="Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.",questType="standard"},
[91619] = {id=91619,name="Blood of Sargeras",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=139,mapID=23,description="We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras. We will need a plentiful quantity. Bring me whatever you can muster.",questType="standard"},
[91620] = {id=91620,name="Noggenfogger's Reasonable Request",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible. Marin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor. Of course, if you would rather, I can eliminate him.",questType="standard"},
[91621] = {id=91621,name="A Taste For Blood",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=5042,mapID=207,starts={{npcID=42470,x=0.568,y=0.14,mapID=207}},ends={{npcID=42470,x=0.568,y=0.14,mapID=207}},coords={x=0.568,y=0.14,source="quest_giver",mapID=207},questType="standard"},
