[91968] = {id=91968,name="Welcome Home",level=0,requiredLevel=0,faction="none",expansion=10,description="What a mess! Perhaps the previous owners left in a hurry. Best tidy up! The items removed will be sent to the house chest. They can always be placed down again, if cobwebs are your thing.",questType="standard"},
[91969] = {id=91969,name="Time to Decorate",level=0,requiredLevel=0,faction="none",expansion=10,description="Now that we've got this place tidied up, let's decorate! The community has chipped in with donations to make sure you have plenty of options to work with. Let's have a look!",questType="standard"},
[92078] = {id=92078,name="A New Recipe!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15336,mapID=2371,starts={{npcID=245348,x=0.42,y=0.224,mapID=2371}},ends={{npcID=245348,x=0.42,y=0.224,mapID=2371}},coords={x=0.42,y=0.224,source="quest_giver",mapID=2371},questType="standard"},
[92082] = {id=92082,name="Someone Like Me",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15336,mapID=2371,starts={{npcID=245344,x=0.42,y=0.222,mapID=2371}},ends={{npcID=245344,x=0.42,y=0.222,mapID=2371}},coords={x=0.42,y=0.222,source="quest_giver",mapID=2371},questType="standard"},
[92420] = {id=92420,name="Ignite the Skies: Southern Kalimdor",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=440,mapID=71,description="Each year, as tribes from southern and central Kalimdor journeyed to Stonetalon to spend the summer season, the rite of the sun blossoms became common practice. Many saw it as a way to give back to An'she, who worked tirelessly during this long season. The rite became especially important towards the end of Midsummer, as the southern tribes journeyed back home. If you're up for another journey, take to the skies once more, my friend, and listen close...",starts={{npcID=251986,x=0.222,y=0.192,mapID=10},{npcID=251986,x=0.316,y=0.636,mapID=71}},ends={{npcID=251986,x=0.222,y=0.192,mapID=10},{npcID=251986,x=0.316,y=0.636,mapID=71}},coords={x=0.222,y=0.192,source="quest_giver",mapID=71},questType="standard"},
[92634] = {id=92634,name="Midsummer's Journey to Loch Modan",level=0,requiredLevel=0,faction="horde",expansion=10,zoneID=6170,mapID=37,description="While Midsummer may be sacred to the tauren, we are not the only people to pay respects to the spirits of fire during the summer months. The Wildhammer, for example, have shared their own customs with us over the years. It seems this time of year has long been important to the dwarves and denizens of the Eastern Kingdoms. Journey to their celebration grounds across the sea in Loch Modan and visit with the Wildhammer. Perhaps they too will tell you a tale...",starts={{npcID=251986,x=0.222,y=0.192,mapID=10},{npcID=251986,x=0.316,y=0.636,mapID=71}},ends={{npcID=266045,x=0.594,y=0.272,mapID=37},{npcID=266045,x=0.744,y=0.014,mapID=37}},coords={x=0.222,y=0.192,source="quest_giver",mapID=37},questType="standard"},
[92647] = {id=92647,name="A Shadowed Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=10565,mapID=1670,description="Champion! The curiosities hidden within the Shadowlands are numerous, as are the dangers. I could use some assistance clearing a path, so to speak. There is much wealth to be gained should you choose to seek it.",questType="standard"},
[92816] = {id=92816,name="A Letter for Adventure",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[92851] = {id=92851,name="Questionable Qualifications",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=2257,mapID=500,description="Well , it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile. That said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.",questType="standard"},
[92855] = {id=92855,name="Make Haste, Not Waste",level=10,requiredLevel=10,faction="both",expansion=10,questType="standard"},
[92857] = {id=92857,name="Ta'readon's Mount Voucher",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=10565,mapID=1670,description="This token bears the seal of Overseer Ta'readon in Oribos . They would be interested in seeing this.",questType="standard"},
[93057] = {id=93057,name="A House For You",level=0,requiredLevel=0,faction="none",expansion=10,description="Greetings, ! Have you ever wanted to own a home? Have a place to call your own? Now you can! Join us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!",questType="standard"},
[93452] = {id=93452,name="Retrieved Crumpled Present",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=16227,questType="standard"},
[93683] = {id=93683,name="Conditional Objectives - Singular",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16105,mapID=2352,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",questType="standard"},
[93877] = {id=93877,name="Conditional Objectives - Sequential",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16432,mapID=2451,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",questType="standard"},
[93878] = {id=93878,name="Conditional Objectives - Multiple Steps, No Sequence",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16432,mapID=2451,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",questType="standard"},
[93879] = {id=93879,name="Conditional Objectives - Conditional After Sequence",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=7637,mapID=680,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",questType="standard"},
[94363] = {id=94363,name="The Gloves Are Off",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=2257,mapID=500,description="If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!",questType="standard"},
[94415] = {id=94415,name="Plumbing the Void",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15781,mapID=2472,starts={{npcID=235252,x=0.406,y=0.292,mapID=2472}},ends={{npcID=235252,x=0.406,y=0.292,mapID=2472}},coords={x=0.406,y=0.292,source="quest_giver",mapID=2472},questType="standard"},
